// ─── File: scripts/TransferSimulation.scala ───  (Gatling: code + reports)
import io.gatling.core.Predef._
import io.gatling.http.Predef._

class TransferSimulation extends Simulation {
  val httpProtocol = http.baseUrl("https://staging.nationalbank.example")

  val scn = scenario("Transfer")
    .exec(http("transfer")
      .post("/api/v1/transfers")
      .body(StringBody("""{"from":"SAV2001","to":"CUR3001","amount":50000}""")).asJson
      .check(status.is(201)))

  setUp(scn.inject(rampUsers(500).during(60)))   // load profile
    .protocols(httpProtocol)
    .assertions(global.responseTime.percentile(95).lt(200))  // p95 < 200ms
}
