package com.bank.qa.perftools;

import java.util.logging.*;

// Recommends a performance tool from team context (not "newest wins").
public class ToolAdvisorDemo {
    private static final Logger log = Logger.getLogger(ToolAdvisorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PToolLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    static String recommend(boolean wantsCiCd, boolean prefersGui, boolean pythonTeam, boolean wantsCodeAndReports) {
        if (prefersGui) return "JMeter (GUI, plugins, mature, broad protocols)";
        if (pythonTeam) return "Locust (Python behavior, simple distributed)";
        if (wantsCiCd) return "k6 (JavaScript, thresholds, CI/CD-first)";
        if (wantsCodeAndReports) return "Gatling (Scala/Java DSL, efficient, rich reports)";
        return "JMeter (safe default)";
    }

    public static void main(String[] args) {
        log.info("=== Choose a performance tool by team/workflow ===");
        log.info("CI/CD-focused JS team   -> " + recommend(true, false, false, false));
        log.info("GUI + plugins (classic) -> " + recommend(false, true, false, false));
        log.info("Python team             -> " + recommend(false, false, true, false));
        log.info("Code + strong reports   -> " + recommend(false, false, false, true));
        log.info("All simulate many virtual users and measure p95/throughput/error rate.");
    }
}

// ─── Would be in PToolLogFormatter.java in a real project ───
class PToolLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
